import { Component, input, output } from '@angular/core';

@Component({
  selector: 'app-tarjeta-tarea',
  template: `
    <h3>{{ tarea().titulo }}</h3>
    <button (click)="completar.emit(tarea().id)">Marcar como hecha</button>
  `,
})
export class TarjetaTarea {
  readonly tarea = input.required<Tarea>();
  readonly completar = output<number>();   // emite el id
}

marcarHecha(id: number) {
  this.tareas.update(lista => lista.map(t => t.id === id ? { ...t, hecha: true } : t));
}

